def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    # Integer Newton's method (Babylonian) for the floor square root.
    # x_{k+1} = (x_k + n // x_k) // 2, starting from an upper bound.
    x = 1 << ((n.bit_length() + 1) // 2)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    # Adjust if needed to ensure x*x <= n < (x+1)^2.
    if x * x > n:
        x -= 1
    if (x + 1) * (x + 1) <= n:
        x += 1
    return x
